    Bug 1936653 - Add show/hide password button in Account Hub. r=aleca

    **How To Test**
    - Update the last lines of `connectedCallback()` to skip ahead and view password stage
    - `this.ready = this.#initUI("emailPasswordSubview");`
    - `this.#emailPasswordSubview.setState();`

    Differential Revision: https://phabricator.services.mozilla.com/D231864

diff --git a/mail/components/accountcreation/content/widgets/email-password-form.mjs b/mail/components/accountcreation/content/widgets/email-password-form.mjs
index 703b37d41ba..679a9960d36 100644
--- a/mail/components/accountcreation/content/widgets/email-password-form.mjs
+++ b/mail/components/accountcreation/content/widgets/email-password-form.mjs
@@ -38,6 +38,13 @@ class EmailPasswordForm extends AccountHubStep {
    */
   #rememberPassword;

+  /**
+   * The show/hide password toggle.
+   *
+   * @type {HTMLButtonElement}
+   */
+  #passwordToggleButton;
+
   connectedCallback() {
     if (this.hasConnected) {
       return;
@@ -53,6 +60,7 @@ class EmailPasswordForm extends AccountHubStep {

     this.#password = this.querySelector("#password");
     this.#rememberPassword = this.querySelector("#rememberPassword");
+    this.#passwordToggleButton = this.querySelector("#passwordToggleButton");

     this.#password.focus();

@@ -60,15 +68,12 @@ class EmailPasswordForm extends AccountHubStep {
     this.#setRememberPasswordInput(this.rememberSignons);

     this.#password.addEventListener("input", this);
+    this.#passwordToggleButton.addEventListener("click", this);
   }

   handleEvent(event) {
     switch (event.type) {
       case "input":
-        if (event.target.id != "password") {
-          break;
-        }
-
         this.dispatchEvent(
           new CustomEvent("config-updated", {
             bubbles: true,
@@ -76,6 +81,20 @@ class EmailPasswordForm extends AccountHubStep {
           })
         );
         break;
+      case "click":
+        {
+          const isNotPressed =
+            event.target.getAttribute("aria-pressed") === "false";
+          this.#password.type = isNotPressed ? "text" : "password";
+          this.#passwordToggleButton.setAttribute("aria-pressed", isNotPressed);
+          document.l10n.setAttributes(
+            this.#passwordToggleButton,
+            isNotPressed
+              ? "account-setup-password-toggle-hide"
+              : "account-setup-password-toggle-show"
+          );
+        }
+        break;
       default:
         break;
     }
